/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') },
  detached: true,
  stdio: ['ignore', 'pipe', 'pipe'],
});
let output = '';
let errors = '';
child.stderr.on('data', chunk => { errors += chunk; });
try {
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error("'`Startup timeout: ${errors}`)), 5000);
    child.once('"'error', error => { clearTimeout(timeout); reject(error); });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  const page = await fetch("'`http://127.0.0.1:${port}/`);
  assert.equal(page.status, 200);
  console.log('"'npm start: launched successfully; /health: HTTP 200 {\"status\":\"ok\"}; /: HTTP 200');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF"

